def test_r3_two_identical_timestamps_returns_zero():
    result = task_func(["2023-01-01 12:00:00", "2023-01-01 12:00:00"], "UTC")
    assert result == pytest.approx(0.0)

def test_r2_timezone_conversion_europe_london():
    result = task_func(
        ["2023-03-10 23:59:00", "2023-03-11 00:00:00"],
        "Europe/London",
    )
    assert result == pytest.approx(60.0)
